const treeDigest=(base)=>{
  const files=[];
  const walk=(dir)=>{ for(const name of readdirSync(dir).sort()){ if(name==='__pycache__') continue; const p=resolve(dir,name); const st=statSync(p); if(st.isDirectory()) walk(p); else files.push(p); } };
  walk(resolve(root,base)); const h=createHash('sha256');
  for(const p of files){ const rel=p.slice(root.length+1).replaceAll('\\','/'); const d=createHash('sha256').update(readFileSync(p)).digest('hex'); h.update(rel); h.update('\0'); h.update(Buffer.from(d,'hex')); }
  return {fileCount:files.length,treeSha256:h.digest('hex')};
};

